const i18nDeWhat={translation:'Übersetzung',rewrite:'Umformulierung',revision:'Überarbeitung'};
const i18nDeWhatAcc=w=>({translation:'die Übersetzung',rewrite:'die Umformulierung',revision:'die Überarbeitung'}[w]||w);
const i18nDeTabs={spelling:'Rechtschreibung',grammar:'Grammatik',punctuation:'Zeichensetzung',wording:'Formulierung','worth checking':'Prüfenswert',formatting:'Formatierung',Spelling:'Rechtschreibung',Grammar:'Grammatik',Punctuation:'Zeichensetzung',Wording:'Formulierung','Worth checking':'Prüfenswert',Formatting:'Formatierung'};
const i18nDeList=s=>s.split(/, | and /).map(x=>i18nDeTabs[x]||x).reduce((a,x,i,arr)=>i===0?x:a+(i===arr.length-1?' und ':', ')+x,'');
const i18nDeVerdict=s=>{const m=s.match(/^(\d+) (.+)$/);if(!m)return s;const w={'supported by the sources found':'von den Quellen gestützt','wrong':'falsch','disputed':'umstritten',"can't verify":'nicht überprüfbar','need context':'brauchen Kontext'}[m[2]];return w?`${m[1]} ${w}`:s;};
const i18nDeExport={'formatted text':'formatierter Text','plain text':'Nur-Text','Markdown':'Markdown','BBCode':'BBCode','M! Forum text':'M!-Forum-Text','Reddit text':'Reddit-Text','YouTube text':'YouTube-Text'};
const i18nDePatterns=[
[/^([\d.,]+) words?$/,n=>`${n.replace(/,/g,'.')} ${n==='1'?'Wort':'Wörter'}`],
[/^(.+), clipboard$/,k=>`${k.replace('Ctrl','Strg')}, Zwischenablage`],
  [/^The correction of "(.+)" would change formatting markup, a link or a tag in the text\. Uncheck it, or edit that spot by hand\.$/,t=>`Die Korrektur von "${t}" würde Auszeichnung, einen Link oder ein Tag im Text ändern. Entferne den Haken oder ändere die Stelle von Hand.`],
  [/^(Summary|Explanation): (.+)$/,(t,v)=>`${tr(t,'de')}: ${tr(v,'de')}`],
  [/^Your answer: (.+)$/,a=>`Deine Antwort: ${a}`],
  [/^Use correction:$/,()=>'Korrektur übernehmen:'],
  [/^Researched in (\d+) s with (.+)$/,(s,m)=>`Recherchiert in ${s} s mit ${m}`],
  [/^Text size (\d+) px \(click to change, or turn the wheel\)$/,s=>`Textgröße ${s} px (klicken zum Ändern oder Mausrad drehen)`],
  [/^Back to (\d+) px$/,s=>`Zurück auf ${s} px`],
  [/^Captured with (.+)$/,s=>`Erfasst mit ${s}`],
  [/^Reset to (.+)$/,s=>`Zurücksetzen auf ${s}`],
  [/^Change the shortcut for (.+)$/,s=>`Kürzel für ${tr(s,'de')} ändern`],
  [/^Set a shortcut for (.+)$/,s=>`Kürzel für ${tr(s,'de')} festlegen`],
  [/^(\d+) min ago$/,n=>`vor ${n} Min.`],
  [/^1 hour ago$/,()=>'vor 1 Stunde'],
  [/^(\d+) hours ago$/,n=>`vor ${n} Stunden`],
  [/^1 day ago$/,()=>'vor 1 Tag'],
  [/^(\d+) days ago$/,n=>`vor ${n} Tagen`],
  [/^Checking (.+)\. Finished tabs are ready to review\.$/,s=>`${i18nDeList(s)} wird geprüft. Fertige Reiter kannst du schon durchsehen.`],
  [/^Review ready\. Not checked: (.+)$/,s=>`Korrektur fertig. Nicht geprüft: ${s.replace(/[A-Z][a-z]+(?: checking)?/g,w=>i18nDeTabs[w]||w)}`],
  [/^(\d+) claims?: (.+)\.$/,(n,list)=>`${n} ${n==='1'?'Behauptung':'Behauptungen'}: ${list.split(', ').map(x=>x.replace(/^(\S+ )?(\d+ .+)$/,(all,sym,rest)=>(sym||'')+i18nDeVerdict(rest))).join(', ')}.`],
  [/^Fact check finished\. (\d+) claims? needs? more context: answer the question on the card\.$/,n=>`Faktencheck fertig. ${n} ${n==='1'?'Behauptung braucht':'Behauptungen brauchen'} mehr Kontext: Beantworte die Frage auf der Karte.`],
  [/^Fact check finished\. (\d+) wrong claims? found\. Review the sources before using a correction\.$/,n=>`Faktencheck fertig. ${n} falsche ${n==='1'?'Behauptung':'Behauptungen'} gefunden. Prüfe die Quellen, bevor du eine Korrektur übernimmst.`],
  [/^Received: (.+)$/,s=>`Empfangen: ${s.replace(/\bPlain text\b/,'Nur Text').replace(/\b(\d+) (CRLF|LF|CR) line ends?\b/g,(a,n,k)=>`${n} ${k}-Zeilenende${n==='1'?'':'n'}`).replace(/\b(\d+) non-breaking spaces?\b/g,(a,n)=>`${n} geschützte${n==='1'?'s Leerzeichen':' Leerzeichen'}`).replace(/\b(\d+) zero-width characters?\b/g,(a,n)=>`${n} Zeichen ohne Breite`)}`],
  [/^Found: (.+)$/,s=>`Gefunden: ${s}`],
  [/^Site-specific elements: (.+)$/,s=>`Seitenspezifische Elemente: ${s}`],
  [/^Rich text( from a rich text editor)?(?:, copied from (.+))?$/,(ed,host)=>`Formatierter Text${ed?' aus einem Rich-Text-Editor':''}${host?`, kopiert von ${host}`:''}`],
  [/^(.+), strong evidence: copied from (.+)$/,(site,host)=>`${site}, eindeutiger Hinweis: kopiert von ${host}`],
  [/^Some links or other objects are missing from the (translation|rewrite)\. Try again before replacing your selection, or copy the \1\.$/,w=>`In der ${i18nDeWhat[w]} fehlen Links oder andere Objekte. Versuche es erneut, bevor du deine Auswahl ersetzt, oder kopiere ${i18nDeWhatAcc(w)}.`],
  [/^Some links or other objects are missing from the (translation|rewrite)\. Nothing was replaced\. Try again, or copy the \1\.$/,w=>`In der ${i18nDeWhat[w]} fehlen Links oder andere Objekte. Es wurde nichts ersetzt. Versuche es erneut oder kopiere ${i18nDeWhatAcc(w)}.`],
  [/^Capture a selection with a shortcut first, or copy the (translation|rewrite)\.$/,w=>`Erfasse zuerst eine Auswahl mit einem Kürzel oder kopiere ${i18nDeWhatAcc(w)}.`],
  [/^Capture a selection with (.+) first, or use Copy revised text\.$/,s=>`Erfasse zuerst eine Auswahl mit ${s} oder kopiere den überarbeiteten Text.`],
  [/^The (translation|rewrite) no longer matches the captured selection\. Capture the text again\.$/,w=>`Die ${i18nDeWhat[w]} passt nicht mehr zur erfassten Auswahl. Erfasse den Text erneut.`],
  [/^This text is read-only\. Copy the (translation|rewrite) and paste it where you need it\.$/,w=>`Dieser Text ist schreibgeschützt. Kopiere ${i18nDeWhatAcc(w)} und füge sie ein, wo du sie brauchst.`],
  [/^This (translation|rewrite) is too long to paste with formatting\.$/,w=>`Diese ${i18nDeWhat[w]} ist zu lang, um sie mit Formatierung einzufügen.`],
  [/^Copied as (.+)\.$/,s=>`Kopiert als ${i18nDeExport[s]||s}.`],
  [/^The setting could not be saved: (.+)$/,s=>`Die Einstellung konnte nicht gespeichert werden: ${s}`],
  [/^Models could not be loaded: (.+)$/,s=>`Modelle konnten nicht geladen werden: ${s}`],
  [/^Uses (.+)$/,s=>`Nutzt ${s}`],
  [/^Use correction: (.*)$/,s=>`Korrektur übernehmen: ${s}`],
  [/^Your answer: (.*)$/,s=>`Deine Antwort: ${s}`],
  [/^Correction: (.*)$/,s=>`Korrektur: ${s}`],
  [/^Paste sent\. TextFixer cannot verify the result in the editor\. Please check it there\. The (translation|revised text) remains on the clipboard\.$/,w=>`Einfügen gesendet. TextFixer kann das Ergebnis im Editor nicht prüfen. Bitte kontrolliere es dort. ${w==='translation'?'Die Übersetzung':'Der überarbeitete Text'} bleibt in der Zwischenablage.`],
  [/^ChatGPT returned an error \((.+)\)\.$/,s=>`ChatGPT hat einen Fehler gemeldet (${s}).`],
  [/^The ChatGPT sign-in failed \((.+)\)\.$/,s=>`Die ChatGPT-Anmeldung ist fehlgeschlagen (${s}).`],
  [/^The selected text is too long( to check| to translate)? \(maximum (.+) characters\)\.$/,(what,n)=>`Der markierte Text ist zu lang${what===' to check'?' für eine Prüfung':what===' to translate'?' für eine Übersetzung':''} (höchstens ${n.replace(/,/g,'.')} Zeichen).`],
  [/^A conversation holds up to (\d+) questions\. Capture the text again to start a new one\.$/,n=>`Ein Gespräch fasst bis zu ${n} Fragen. Erfasse den Text erneut, um ein neues zu beginnen.`],
  [/^Keep each answer under (.+) characters\.$/,n=>`Halte jede Antwort unter ${n.replace(/,/g,'.')} Zeichen.`],
  [/^Keep the change request under (.+) characters\.$/,n=>`Halte den Änderungswunsch unter ${n.replace(/,/g,'.')} Zeichen.`],
  [/^Keep the context under (.+) characters\.$/,n=>`Halte den Kontext unter ${n.replace(/,/g,'.')} Zeichen.`],
  [/^Keep the question under (.+) characters\.$/,n=>`Halte die Frage unter ${n.replace(/,/g,'.')} Zeichen.`],
  [/^(.+) (?:is|are) used by another app\.(.*)$/,(names,rest)=>`${names} ${names.includes(',')||names.includes(' and ')?'werden':'wird'} von einer anderen App genutzt.${rest}`],
  [/^Post by (.+)$/,s=>`Beitrag von ${s}`]
];
